<?php
declare(strict_types=1);

require_once __DIR__ . '/includes/init.php';
require_once __DIR__ . '/csrf_helper.php';
require_once __DIR__ . '/includes/club_event.php';
require_once __DIR__ . '/includes/club_event_registration.php';
if (!isset($_SESSION['trener_id']) || !roleAtLeast('admin')) { header('Location: login.php'); exit; }
function eventAdminH(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!csrf_verify((string)($_POST['csrf_token']??''))) $errors[]='Formulář vypršel. Obnovte stránku.';
    else {
        try {
            $action=(string)($_POST['action']??'');$eventId=(int)($_POST['event_id']??0);$actor=(int)$_SESSION['trener_id'];
            if ($action==='create') {
                $result=clubEventCreateDraft($pdo,$actor,$_POST);$eventId=$result['id'];$_SESSION['flash_event_success']='Pracovní klubová akce byla založena.';
            } elseif ($action==='add_session') {
                clubEventAddSession($pdo,$eventId,$actor,(string)($_POST['starts_at']??''),(string)($_POST['ends_at']??''),(string)($_POST['location']??''),($_POST['capacity_override']??'')===''?null:(int)$_POST['capacity_override']);$_SESSION['flash_event_success']='Termín byl přidán.';
            } elseif ($action==='link_product') {
                $result=clubEventLinkProduct($pdo,$eventId,(int)($_POST['product_id']??0),$actor,(string)($_POST['note']??''));$_SESSION['flash_event_success']=$result['created']?'Produkt byl propojen s akcí.':'Produkt už byl s akcí propojen.';
            } elseif ($action==='unlink_product') {
                clubEventUnlinkProduct($pdo,$eventId,(int)($_POST['link_id']??0),$actor,(string)($_POST['note']??''));$_SESSION['flash_event_success']='Produkt byl od akce odpojen.';
            } elseif ($action==='configure_terms') {
                $result=clubEventConfigureRegistrationTerms($pdo,$eventId,$actor,(string)($_POST['terms_version']??''),(string)($_POST['consent_text_plain']??''),(string)($_POST['cancellation_policy_plain']??''),(string)($_POST['cancellation_deadline_at']??''),($_POST['confirm_terms']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Souhlas a storno podmínky byly uloženy.':'Podmínky se nezměnily.';
            } elseif ($action==='open_free') {
                $result=clubEventOpenFreeRegistration($pdo,$eventId,$actor,(string)($_POST['note']??''),($_POST['confirm_open']??'')==='1');$_SESSION['flash_event_success']=$result['changed']?'Bezplatný kroužek byl otevřen pro přihlášení.':'Kroužek už je otevřený.';
            } elseif ($action==='close_registration') {
                $result=clubEventCloseRegistration($pdo,$eventId,$actor,(string)($_POST['note']??''));$_SESSION['flash_event_success']=$result['changed']?'Přihlašování bylo uzavřeno.':'Přihlašování už bylo uzavřeno.';
            } else throw new InvalidArgumentException('Neplatná akce.');
            header('Location: eshop_events_admin.php?event_id='.$eventId,true,303);exit;
        } catch (PDOException $exception) { error_log('eshop_events_admin.php: '.$exception->getMessage());$errors[]='Databázová operace selhala bez částečného zápisu.'; }
        catch (InvalidArgumentException|ClubEventException|ClubEventRegistrationException $exception) { $errors[]=$exception->getMessage(); }
    }
}
$success=(string)($_SESSION['flash_event_success']??'');unset($_SESSION['flash_event_success']);
$events=clubEventList($pdo);$eventId=max(0,(int)($_GET['event_id']??0));if ($eventId===0&&$events!==[])$eventId=(int)$events[0]['id'];$detail=$eventId?clubEventDetail($pdo,$eventId):null;
$registrationCount=0;$effectiveCapacity=0;if($detail){$capacityStatement=$pdo->prepare("SELECT COUNT(*) FROM club_event_registrations WHERE event_id=? AND status='confirmed'");$capacityStatement->execute([$eventId]);$registrationCount=(int)$capacityStatement->fetchColumn();$effectiveCapacity=clubEventEffectiveCapacity($pdo,$eventId,(int)$detail['event']['capacity']);}
$products=$pdo->query("SELECT p.id,p.name,p.offer_type,p.catalog_status FROM shop_products p WHERE p.offer_type IN ('club_event','camp') AND NOT EXISTS (SELECT 1 FROM shop_product_event_links l WHERE l.product_id=p.id) ORDER BY p.name,p.id")->fetchAll(PDO::FETCH_ASSOC);
?>
