="registration_starts_at"></div><div class="col-md-3"><label class="form-label">Registrace do</label><input class="form-control" type="datetime-local" name="registration_ends_at"></div><div class="col-md-3 d-grid align-self-end"><button class="btn btn-primary">Založit draft akce</button></div></form></div></div>
<div class="row g-3 mb-3"><?php foreach($events as $event):$statusColor=$event['status']==='open'?'success':($event['status']==='closed'?'secondary':'warning');?><div class="col-md-4 col-xl-3"><a class="text-decoration-none text-reset" href="eshop_events_admin.php?event_id=<?=(int)$event['id']?>"><div class="card h-100 shadow-sm <?=$eventId===(int)$event['id']?'border-primary':'border-0'?>"><div class="card-body"><div class="d-flex justify-content-between"><strong><?=eventAdminH($event['name'])?></strong><span class="badge bg-<?=$statusColor?> <?=$statusColor==='warning'?'text-dark':''?>"><?=eventAdminH($event['status'])?></span></div><code><?=eventAdminH($event['code'])?></code><div class="small text-muted mt-2"><?=(int)$event['session_count']?> termínů · <?=(int)$event['product_count']?> produktů · kapacita <?=(int)$event['capacity']?></div></div></div></a></div><?php endforeach;?></div>
<?php if($detail):$event=$detail['event'];?><div class="card border-0 shadow-sm mb-3"><div class="card-header bg-white d-flex justify-content-between"><span><strong><?=eventAdminH($event['name'])?></strong> <code><?=eventAdminH($event['event_type'])?></code></span><span><?=$registrationCount?> / <?=$effectiveCapacity?> přihlášeno</span></div><div class="card-body"><?php if($event['status']==='draft'&&$event['event_type']==='club_event'&&$event['pricing_policy']==='free'):?><form method="post" class="row g-2 border-bottom pb-3 mb-3"><?=csrf_field()?><input type="hidden" name="action" value="configure_terms"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="col-md-2"><label class="form-label">Verze souhlasu</label><input class="form-control" name="terms_version" maxlength="64" pattern="[A-Za-z0-9._-]+" required value="<?=eventAdminH($event['terms_version']??'')?>" placeholder="2026.1"></div><div class="col-md-5"><label class="form-label">Text souhlasu</label><textarea class="form-control" name="consent_text_plain" maxlength="4000" rows="3" required><?=eventAdminH($event['consent_text_plain']??'')?></textarea></div><div class="col-md-5"><label class="form-label">Storno podmínky</label><textarea class="form-control" name="cancellation_policy_plain" maxlength="4000" rows="3" required><?=eventAdminH($event['cancellation_policy_plain']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Bezplatné storno do</label><input class="form-control" type="datetime-local" name="cancellation_deadline_at" required value="<?=eventAdminH(isset($event['cancellation_deadline_at'])&&$event['cancellation_deadline_at']!==null?str_replace(' ','T',substr((string)$event['cancellation_deadline_at'],0,16)):'')?>"></div><div class="col-md-5 form-check align-self-center"><input class="form-check-input" type="checkbox" name="confirm_terms" value="1" id="confirm-terms" required><label class="form-check-label" for="confirm-terms">Potvrzuji toto znění a termín</label></div><div class="col-md-3 d-grid align-self-end"><button class="btn btn-outline-primary">Uložit podmínky</button></div></form><form method="post" class="row g-2 border-bottom pb-3 mb-3"><?=csrf_field()?><input type="hidden" name="action" value="open_free"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="col-md-5"><input class="form-control" name="note" maxlength="1000" required placeholder="Důvod otevření"></div><div class="col-md-4 form-check align-self-center"><input class="form-check-input" type="checkbox" name="confirm_open" value="1" id="confirm-open" required><label class="form-check-label" for="confirm-open">Potvrzuji otevření přihlášek</label></div><div class="col-md-3 d-grid"><button class="btn btn-success">Otevřít bezplatný kroužek</button></div></form><?php elseif($event['status']==='open'):?><div class="alert alert-light border"><strong>Souhlas <?=eventAdminH($event['terms_version'])?></strong><br><?=nl2br(eventAdminH($event['consent_text_plain']))?><hr><strong>Storno do <?=eventAdminH($event['cancellation_deadline_at'])?></strong><br><?=nl2br(eventAdminH($event['cancellation_policy_plain']))?></div><form method="post" class="row g-2 border-bottom pb-3 mb-3"><?=csrf_field()?><input type="hidden" name="action" value="close_registration"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="col-md-9"><input class="form-control" name="note" maxlength="1000" required placeholder="Důvod uzavření přihlašování"></div><div class="col-md-3 d-grid"><button class="btn btn-outline-danger">Uzavřít přihlašování</button></div></form><?php endif;?><div class="row g-3"><div class="col-lg-6"><h2 class="h6">Přidat termín</h2><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="add_session"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="col-6"><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col-6"><input class="form-control" type="datetime-local" name="ends_at" required></div><div class="col-7"><input class="form-control" name="location" maxlength="255" required placeholder="Místo"></div><div class="col-3"><input class="form-control" type="number" name="capacity_override" min="1" max="10000" placeholder="Kapacita"></div><div class="col-2 d-grid"><button class="btn btn-outline-primary">Přidat</button></div></form><div class="mt-2"><?php foreach($detail['sessions'] as $session):?><div class="border-bottom py-2"><strong><?=eventAdminH($session['starts_at'])?> – <?=eventAdminH($session['ends_at'])?></strong><div class="small text-muted"><?=eventAdminH($session['location'])?><?=$session['capacity_override']?' · kapacita '.(int)$session['capacity_override']:''?></div></div><?php endforeach;?></div></div>
<div class="col-lg-6"><h2 class="h6">Propojit produkt stejného typu</h2><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="link_product"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="col-6"><select class="form-select" name="product_id" required><option value="">Vyberte produkt</option><?php foreach($products as $product):if($product['offer_type']!==$event['event_type'])continue;?><option value="<?=(int)$product['id']?>"><?=eventAdminH($product['name'])?> (<?=eventAdminH($product['catalog_status'])?>)</option><?php endforeach;?></select></div><div class="col-4"><input class="form-control" name="note" maxlength="1000" required placeholder="Důvod propojení"></div><div class="col-2 d-grid"><button class="btn btn-outline-success">Propojit</button></div></form><?php foreach($detail['products'] as $product):?><form method="post" class="d-flex gap-2 border-bottom py-2 align-items-center"><?=csrf_field()?><input type="hidden" name="action" value="unlink_product"><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="link_id" value="<?=(int)$product['id']?>"><span class="flex-grow-1"><strong><?=eventAdminH($product['product_name'])?></strong> <code><?=eventAdminH($product['offer_type'])?></code></span><input class="form-control form-control-sm" style="max-width:220px" name="note" maxlength="1000" required placeholder="Důvod odpojení"><button class="btn btn-sm btn-outline-danger">Odpojit</button></form><?php endforeach;?></div></div></div></div>
